window.__BUNDLE__={"generatedAt":"2026-09-21T05:23:53.054308+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-14","archiveCutoff":"2021-09-22","addedToday":242,"addedThisRun":242,"fetchStats":{"hf":202,"arxiv":1236,"total":1438},"freshness":{"latestPaperDate":"2026-09-21","latestPublishedDate":"2026-09-21","latestBatchCount":201,"newInLast24h":242,"newInLast48h":242},"historyTotal":15075,"topicCounts":{"Multi-Agent":2122,"Evaluation":8028,"Planning":1212,"Memory":308,"Code Agent":632,"Interpretability":557,"Agentic RAG":1174,"Agentic Search":1471,"RL for LLM":928,"Reasoning":4336,"Hallucination":857,"Post-Training":1782,"Alignment":2059,"World Model":201,"Tool Use":1140,"Agent Safety":2197,"Computer Use":248,"Reflection":565,"VLM Training":976,"LLM Training":1746,"Fine-tuning":2243,"Multimodal Agent":90,"Agent Framework":741,"Error Attribution":109,"Data Engine":322},"count":36,"recentTotal":1876,"archiveCount":0,"archiveTotal":13199,"sources":{"hf":45,"arxiv":1831,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"id":"arxiv:2609.22000","tags":["Evaluation"],"source":"hf","url":"https://arxiv.org/abs/2609.22000","upvotes":31,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22000.pdf","arxiv":"https://arxiv.org/abs/2609.22000","date":"2026-09-21","topics":["Evaluation"],"authors":["Shuai Bai","Jiayong Deng","Yikun Fu","Chang Gao","Xuhao Hu","Mianqiu Huang","Yizhen Jiang","Yuheng Jing","Dehui Kong","Keliang Li","Ning Li","Wanli Li","Dayiheng Liu","Dunjie Lu","Changwei Luo","Que Shen","Zheyuan Wang","Zijian Wang","Jie Wu","Gao Wu","Zhihui Xie","Rui Xie","Haiyang Xu","An Yang","Jiakang Yuan","Yanming Zhang","Jiajun Zhang","Xi Zhang","Zhenru Zhang","Zhuo Zhen","Mingkang Zhu","Bowen Zhou"],"title":"RecreationWorld: Scalable and Verifiable Environments for Hybrid Computer-Use Agents","hfUrl":"https://huggingface.co/papers/2609.22000","abstract":"Computer-use agents (CUAs) have advanced along two separate lines: graphical interaction and software development through code and the command line. Real digital work requires both, interleaved rather than stacked end to end. We study hybrid CUAs that autonomously decide when to explore an interface, implement software, and run and visually verify their artifacts. We introduce RecreationWorld, a five-platform framework built around recreation: given a running reference, an agent must discover its behavior and build a faithful implementation with no prescribed workflow. RecreationWorld provides reproducible environments on Ubuntu, macOS, Windows, Android, and Web, plus a unified harness with native GUI control and coding tools. The running reference serves as an oracle for hidden behavioral tests, providing execution-grounded rewards. We scale trajectory generation with high-quality open-"},{"id":"arxiv:2609.22068","tags":["Post-Training","Code Agent","Evaluation"],"source":"hf","url":"https://arxiv.org/abs/2609.22068","upvotes":29,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22068.pdf","arxiv":"https://arxiv.org/abs/2609.22068","date":"2026-09-21","topics":["Post-Training","Code Agent","Evaluation"],"authors":["Bowen Ye","Lei Li","Shicheng Li","Zihao Yue","Linghao Zhang","Hanglong Lv","Yuanxin Liu","Wenhan Ma","Hao Tian","Rang Li","Jinhao Dong","Yikai Zhao","Xiangwei Deng","Hailin Zhang","Liang Zhao","Qi Liu","Lingpeng Kong","Tong Yang","Fuli Luo"],"title":"CodeMidas: Scaling Agentic Coding RL Environments from Code Itself","hfUrl":"https://huggingface.co/papers/2609.22068","abstract":"Training capable coding agents via reinforcement learning (RL) requires diverse tasks with reliable verifiers. Open-source codebases offer a rich source of such tasks, while existing methods typically rely on development artifacts such as issues and commits, limiting the range of tasks that can be extracted. To better scale RL environments, we present CodeMidas, an agentic pipeline that turns implemented functionality in existing codebases into executable RL environments using source code as its only task-specific input. CodeMidas allocates agentic compute to every stage of environment construction: agents explore implemented functionality to formulate behavioral specifications, construct tests grounded in execution of the original code, and validate and filter candidate tasks through execution checks and repeated solution rollouts. The resulting dataset has 5,545 training tasks from 3,1"},{"id":"arxiv:2609.21749","tags":["Evaluation","Reflection"],"source":"hf","url":"https://arxiv.org/abs/2609.21749","upvotes":4,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21749.pdf","arxiv":"https://arxiv.org/abs/2609.21749","date":"2026-09-21","topics":["Evaluation","Reflection"],"authors":["Rui Sun","Zhi Zheng","Zhenkun Wang","Zhichao Lu"],"title":"GraphSkillEvo: Evolutionary Optimization of Graph-Structured Agent Skills","hfUrl":"https://huggingface.co/papers/2609.21749","abstract":"Skills can improve the performance of Large Language Model (LLM) agents by providing task-specific procedural guidance, while skill optimization further improves their effectiveness through iterative refinement. However, existing skill optimization methods typically represent skills as unstructured natural-language instructions, creating two key challenges: 1) Unstructured skills often lack explicit workflow-level guidance and contain substantial redundancy, making them difficult for LLMs to execute; 2) the vast search space of unconstrained natural-language skills makes skill optimization ineffective. To address these challenges, we propose representing skills as graph-structured natural-language artifacts. In graph-structured skills, each node represents an execution step together with its operational guidance, while directed edges encode context-dependent transitions between steps. Co"},{"id":"arxiv:2609.22083","tags":["VLM Training","Tool Use","Evaluation","Multimodal Agent"],"source":"hf","url":"https://arxiv.org/abs/2609.22083","upvotes":2,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22083.pdf","arxiv":"https://arxiv.org/abs/2609.22083","date":"2026-09-21","topics":["VLM Training","Tool Use","Evaluation","Multimodal Agent"],"authors":["Mingfei Gao","Rui Tian","Haiming Gang","Bohan Zhai","Le Zhang","Yuanzheng Gong","Di Feng","Ege Özsoy","Kaixin Ma","Vishwesh Kirthivasan","Oğuzhan Fatih Kar","Roman Bachmann","Anders Boesen Lindbo Larsen","Afshin Dehghan"],"title":"MintAct: A Unified Visual Agent for Digital Environments","hfUrl":"https://huggingface.co/papers/2609.22083","abstract":"We present MintAct, a family of vision-language models that unifies UI grounding, multi-step navigation across mobile, desktop, and web, and visual tool use, trained at 2B, 4B, and 8B scales. Through careful design of our environments, data, and training recipes, MintAct models match the performance of per-domain specialists across all of these capabilities. To enable this, we develop a scalable environment and reinforcement learning (RL) infrastructure. On the environment side, we host hundreds of concurrent instances across heterogeneous per-domain backends, serving both trajectory data collection and online RL. To enable efficient and scalable RL training, an asynchronous framework keeps explicit control over the cross-domain training distribution and remains stable under noisy environment feedback and off-policy drift. Experimental results show that MintAct achieves state-of-the-art "},{"id":"arxiv:2609.20942","tags":["Evaluation","Alignment","Fine-tuning"],"source":"hf","url":"https://arxiv.org/abs/2609.20942","upvotes":2,"submittedDate":"2026-09-17","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.20942.pdf","arxiv":"https://arxiv.org/abs/2609.20942","date":"2026-09-21","topics":["Evaluation","Alignment","Fine-tuning"],"authors":["Sy-Tuyen Ho","Minghui Liu","Furong Huang"],"title":"When AI Reviews Train AI Reviewers: Scientific-Judgment Collapse and Mitigation","hfUrl":"https://huggingface.co/papers/2609.20942","abstract":"Large language models (LLMs) increasingly participate in scientific evaluation, both as automated reviewers and as assistants to human reviewers. As model-generated reviews enter public data and future training corpora, AI peer review can become recursive: later reviewers learn from judgments produced by earlier models. We study one step of this feedback loop in a controlled setting. Starting from Llama 3.1 8B, we first fine-tune a reviewer on official ICLR reviews from 2018--2023 and then train four successor models on ICLR 2024 data with systematically varied mixtures of official and model-generated reviews. Our study shows that introducing synthetic reviews compresses rating distributions and reduces both same-paper and corpus-level semantic diversity. We call this pattern $\\textbf{scientific-judgment collapse}$. To mitigate this failure mode, we introduce $\\textbf{TrustReviewer}$, an"},{"id":"arxiv:2609.21619","tags":["Reasoning","Evaluation"],"source":"hf","url":"https://arxiv.org/abs/2609.21619","upvotes":1,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21619.pdf","arxiv":"https://arxiv.org/abs/2609.21619","date":"2026-09-21","topics":["Reasoning","Evaluation"],"authors":["Qiangqiang He","Jin Li","MingCai Chen"],"title":"Calibrating Teacher--Student Discrepancy for On-Policy Distillation","hfUrl":"https://huggingface.co/papers/2609.21619","abstract":"On-policy distillation (OPD) improves reasoning models by learning the token-level discrepancy between a stronger teacher and an on-policy student. However, this discrepancy does not purely reflect the capability gap between the teacher and the student: it also contains deviations arising from the teacher itself, which are consequently mixed into the observed teacher--student discrepancy and indiscriminately learned by standard OPD during training. This issue is further exacerbated by privileged OPD, where privileged information induces larger teacher-side likelihood shifts, thereby encouraging the student to learn more of the teacher's own deviation. We introduce \\textbf{Calibrated On-Policy Distillation (Cal-OPD)}, which estimates the teacher's self-deviation region through positive and negative privileged interventions and calibrates the original teacher--student discrepancy by retain"},{"id":"arxiv:2609.22069","tags":["LLM Training","Evaluation"],"source":"hf","url":"https://arxiv.org/abs/2609.22069","upvotes":1,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22069.pdf","arxiv":"https://arxiv.org/abs/2609.22069","date":"2026-09-21","topics":["LLM Training","Evaluation"],"authors":["Wenxue Li","Peiyan Guan","Haoyang Jiang","Junxian Cai","Hualuo Liu","Chunjie Zhang","Chong Guan","Songlian Li","Taiyi Wu","Yongjian Yu","Xiaotong Zhao","Alan Zhao","Eric Liu","Xi Chen","Yu Liu","Lei Zhu"],"title":"OmniVBench: A Benchmark and Large-Scale Dataset for Omni Reference-to-Video Generation","hfUrl":"https://huggingface.co/papers/2609.22069","abstract":"Reference-to-video (R2V) generation is evolving toward increasingly general and versatile reference control, giving rise to the emerging paradigm of omni R2V generation. However, existing benchmarks fall short of these emerging capabilities: their test cases cover limited reference types and compositions, and their evaluation protocols largely assess holistic reference consistency, overlooking whether reference factors are properly preserved, disentangled, and routed. Meanwhile, the high cost of constructing omni R2V training data makes suitable training resources scarce. To address these gaps, we introduce OmniVBench and the Omni-R2V Dataset for evaluating and training omni R2V models. OmniVBench expands R2V evaluation across broader reference types, fine-grained control tasks, and richer reference compositions, covering 7 task families and 18 fine-grained tasks spanning content, motion"},{"id":"arxiv:2609.20886","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.20886","upvotes":0,"submittedDate":"2026-09-16","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.20886.pdf","arxiv":"https://arxiv.org/abs/2609.20886","date":"2026-09-21","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Chuxuan Hu","Yeye He","Penny Zhou","Wee Hyong Tok","Daniel Kang","Surajit Chaudhuri"],"title":"BI-Agent and BI-Bench: Towards Automating End-to-End Business Intelligence","abstract":"Business intelligence (BI) is a cornerstone of enterprise decision-making and is widely used by enterprise users in software such as Power BI and Tableau. In traditional BI workflows, users need to prepare data by (1) identifying relevant tables, (2) performing data transformations, and (3) building join relationships, before they can (4) answer their business questions. These steps can be complex and time-consuming, making BI challenging. Given the strong capabilities of large language models (LLMs) in working with data, we study their ability to answer BI questions end-to-end, without requiring users to manually perform the tedious preparation steps. To do this, we harvest a large collection of real-world BI projects from public sources, and manually extract pairs of (questions, ground-truth answers) from real user dashboards. The resulting benchmark, BI-Bench, is the first benchmark t"},{"id":"arxiv:2609.21263","tags":["VLM Training","Multi-Agent","Reasoning","Evaluation","Agent Framework"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21263","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21263.pdf","arxiv":"https://arxiv.org/abs/2609.21263","date":"2026-09-21","topics":["VLM Training","Multi-Agent","Reasoning","Evaluation","Agent Framework"],"authors":["Qiufeng Li","Chengxuan Wang","Rongqian Chen","Quan Cheng","Yihui Ren","Chia-Tung Ho","David Z. Pan","Tian Lan","Weidong Cao"],"title":"PlaceReasoner-Beta: Reasoning-Driven Macro Placement and Benchmarking","abstract":"Automated macro placement remains a fundamental challenge in VLSI physical design. Despite decades of research, existing approaches predominantly optimize hand-crafted proxy objectives, such as estimated wirelength, and typically produce placements through one-shot numerical optimization, limiting their ability to incorporate visual layout context, codified design expertise, and downstream physical-design feedback in a unified loop. We present PlaceReasoner-Beta, a verifier-guided multi-agent framework that reformulates macro placement as a closed-loop reasoning problem rather than black-box optimization. A vision-language model (VLM) planner generates candidate placements from the floorplan image, macro specifications, and connectivity structure; a geometric verifier enforces physical legality and expert placement principles; a physical verifier refines candidates using early implementa"},{"id":"arxiv:2609.21879","tags":["VLM Training","Hallucination","Evaluation","Alignment","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21879","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21879.pdf","arxiv":"https://arxiv.org/abs/2609.21879","date":"2026-09-21","topics":["VLM Training","Hallucination","Evaluation","Alignment","Fine-tuning"],"authors":["Laurent Colbois","Sébastien Marcel"],"title":"Benchmarking the Explanatory Quality of Open-Weight Vision-Language Models in Face Recognition","abstract":"Vision-Language Models (VLMs) have recently been proposed as promising tools for face recognition, as they can produce natural language explanations alongside similarity scores. This capability is considered appealing for face comparisons in forensic contexts, which require decisions to be transparent and auditable. However, existing evaluations of VLMs for that use case focus mostly on recognition accuracy, while the validity of generated explanations remains unquantified. In this work, we introduce a benchmarking framework for VLM-based face recognition that treats explanation quality as a core evaluation axis. We propose two criteria that explanations should satisfy: relevance, i.e., reliance on identity-stable facial features; and faithfulness, i.e., alignment with the visible image content without hallucinated features. We jointly develop a methodology enabling the quantification of"},{"id":"arxiv:2609.21075","tags":["Post-Training","LLM Training","Evaluation","Alignment","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21075","upvotes":0,"submittedDate":"2026-09-17","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21075.pdf","arxiv":"https://arxiv.org/abs/2609.21075","date":"2026-09-21","topics":["Post-Training","LLM Training","Evaluation","Alignment","Fine-tuning"],"authors":["Mohit Chandra","Nabin Kim","Eli Min","Aamogh Sawant","Tanmay Sutar","Munmun De Choudhury"],"title":"Aligning with Lived Experience: Heterogeneous Benefits of Fine Tuning in Mental Health Support Generation","abstract":"As access to professional mental healthcare remains limited, many individuals turn to online platforms such as Reddit to seek peer support situated within human lived experience. However, a significant portion of such queries go unanswered, presenting an opportunity for using Large Language Models (LLMs) to fill this gap. While LLMs have demonstrated strong performance on clinical benchmarks, their ability to generate lived-experience informed and community-aligned peer support is underexplored. Addressing this gap, we introduce the COmmunity-centered Peer Engaged Support (COPES) dataset and a three-axis evaluation framework to assess LLM alignment with community perspectives to mental health support seeking queries. Evaluating zero-shot and post-trained (SFT and DPO) models, we show that post-training on COPES significantly improves Strategy Alignment (>50% for general-purpose models) a"},{"id":"arxiv:2609.20842","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"source":"arxiv","url":"https://arxiv.org/abs/2609.20842","upvotes":0,"submittedDate":"2026-08-04","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.20842.pdf","arxiv":"https://arxiv.org/abs/2609.20842","date":"2026-09-21","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"authors":["Qifeng Cai","Xuanguang Pan","Hao Liang","Chang Xu","Wentao Zhang"],"title":"COAL-SQL: Coverage-Guided Augmentation and Failure-Driven Learning for Text-to-SQL Post-Training","abstract":"Text-to-SQL translates natural-language questions into executable SQL queries, but open-source large language models still require task-specific post-training for complex, real-world SQL generation. Effective post-training requires both training data that cover the capabilities demanded by the target task and a learning strategy that enables the model to acquire them. Existing datasets provide valuable supervision but incompletely cover SQL structures, while augmentation methods typically expand data without identifying structural gaps. Moreover, supervised fine-tuning (SFT) or reinforcement learning (RL) alone cannot dynamically address weaknesses exposed during training. We propose COAL-SQL, a unified framework combining Coverage-Guided Augmentation (CGA) and Failure-Driven Learning (FDL). CGA uses greedy selection to identify SQL structures missing from the original dataset and constr"},{"id":"arxiv:2609.21843","tags":["Error Attribution","Multi-Agent","Reasoning","Evaluation","Agent Framework"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21843","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21843.pdf","arxiv":"https://arxiv.org/abs/2609.21843","date":"2026-09-21","topics":["Error Attribution","Multi-Agent","Reasoning","Evaluation","Agent Framework"],"authors":["Eric Jansson","Per Strandberg","Thomas Sörensen","Eduard Paul Enoiu","Wasif Afzal"],"title":"Supporting Industrial Test-Failure Analysis with LLM-Based Systems: An Experience Report","abstract":"This study examines tool-augmented Large Language Model (LLM) systems for supporting Root Cause Analysis (RCA) of nightly test failures at Westermo Network Technologies AB. Nightly test executions produce heterogeneous test data and logs that practitioners currently inspect manually across multiple sources. We implemented an RCA workflow in single-agent and orchestrated multi-agent configurations, both with access to test metadata and logs. An exploratory industrial case study used two real failure scenarios. Six practitioners evaluated the scenario reports through a survey and focus group, and operational measurements were collected from 120 repeated executions. The evaluation covered practitioner-perceived correctness, reasoning quality, fix realism, clarity, usefulness, and trust, as well as cost, duration, and consistency. Neither configuration showed a consistent practitioner-percei"},{"id":"arxiv:2609.21675","tags":["Post-Training","Reasoning","Hallucination","Evaluation","RL for LLM"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21675","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21675.pdf","arxiv":"https://arxiv.org/abs/2609.21675","date":"2026-09-21","topics":["Post-Training","Reasoning","Hallucination","Evaluation","RL for LLM"],"authors":["Wan Xu","Yuanfan Guo","Kevin Han","LaLa Chen","Wangmeng Zuo"],"title":"DRT: Dense Reasoning Trace for Efficient and Grounded Multimodal Reasoning","abstract":"Despite the remarkable progress in Multimodal Large Language Models (MLLMs), prevailing Chain-of-Thought (CoT) paradigms remain confined to the natural-language expression space. Consequently, they inherently incur excessive linguistic overhead, leading to information dilution and weak visual grounding. To address this challenge, we propose Dense Reasoning Trace (DRT), a paradigm that departs from natural-language-centered CoT by expressing reasoning as compact structured traces, which include concise intermediate states with symbolic connectors and disentangle visual observations from logical deductions. First, we introduce the Dense Trace Initialization to internalize the DRT reasoning mode into the model, substantially improving token efficiency while preserving visual evidence. To further enable the model to faithfully capture the logical relations within traces, we propose the Trace"},{"id":"arxiv:2609.21492","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21492","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21492.pdf","arxiv":"https://arxiv.org/abs/2609.21492","date":"2026-09-21","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Jingyu Hu","Shu Yang","Weiru Liu","Di Wang"],"title":"LogicTrack: Auditing Reasoning Trajectories of Large Language Models with Formal Logic Solvers","abstract":"Chain-of-Thought (CoT) reasoning has been shown to improve the performance of large language models (LLMs), yet existing optimization methods largely rely on outcome-based feedback, leaving the logical validity of intermediate reasoning steps largely unverified. To address the gap whereby LLMs arrive at correct final answers through logically flawed intermediate reasoning chains, we propose LogicTrack, a neuro-symbolic framework that audits reasoning trajectories by auto-formalizing each reasoning step into symbolic representations and verifying it with automated theorem provers. LogicTrack introduces Solver-Based Backtracking Reward (SBR), a step-wise scoring mechanism that quantifies logical soundness and guides backtracking tree search at inference time. We further extend LogicTrack to construct supervised fine-tuning (SFT) data with backtracking traces from its trajectories, enabling"},{"id":"arxiv:2609.21650","tags":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21650","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21650.pdf","arxiv":"https://arxiv.org/abs/2609.21650","date":"2026-09-21","topics":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"authors":["Hiroaki Kingetsu","Hiroaki Kurihara","Kaoru Yokoo","Kenji Fukumizu","Manohar Kaul"],"title":"SynthDemo-RL: Breaking the Zero-Reward Barrier in VLA Adaptation with LLM-Guided Synthetic Demonstrations","abstract":"Fine-tuning Vision-Language-Action (VLA) models commonly relies on human teleoperation demonstrations, while reinforcement learning (RL) with sparse binary rewards faces an exploration challenge when successful trajectories are rarely sampled. We propose SynthDemo-RL, a teacher-student framework in which an automated teacher converts simulator-privileged state into successful manipulation trajectories, a VLA student is distilled from them by supervised fine-tuning (SFT), and PPO with binary task-success rewards refines the student. We study reward coverage, the fraction of tasks for which at least one success is observed under the fixed evaluation protocol, as a complement to the average success rate. On LIBERO-PRO, a public benchmark of perturbed LIBERO tasks for which no demonstrations exist, 27 of 57 scored tasks are at exactly 0% success for a pi_0.5 policy fine-tuned on the original"},{"id":"arxiv:2609.21276","tags":["Post-Training","VLM Training","Reasoning","Evaluation"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21276","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21276.pdf","arxiv":"https://arxiv.org/abs/2609.21276","date":"2026-09-21","topics":["Post-Training","VLM Training","Reasoning","Evaluation"],"authors":["Jia Li","Li Dai","Peng Jia","Zhenzhen Hu","Chee Seng Chan","Bingkun Bao","Richang Hong"],"title":"Beyond Exact Match: Task-Aware GRPO for Cross-Domain PCBA Visual Question Answering","abstract":"In automated Printed Circuit Board Assembly (PCBA) inspection, standards-guided decisions require systems to jointly reason over fine-grained visual cues, component semantics, and manufacturing knowledge. Although large vision-language models (VLMs) provide a promising foundation, their deployment is hindered by the domain shift between standards-derived samples and real-world production-line imagery, together with heterogeneous output spaces spanning choice-based and numerical counting tasks. To address these challenges, we propose a multimodal reasoning framework for cross-domain PCBA visual question answering. The framework converts standards-derived, real-world, and auxiliary PCB-domain data into a unified instruction format and constructs verified reasoning traces aligned with visual evidence, question semantics, candidate options, and ground-truth answers. We further introduce Task"},{"id":"arxiv:2609.21094","tags":["Post-Training","Evaluation","Alignment","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21094","upvotes":0,"submittedDate":"2026-09-17","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21094.pdf","arxiv":"https://arxiv.org/abs/2609.21094","date":"2026-09-21","topics":["Post-Training","Evaluation","Alignment","Fine-tuning"],"authors":["Utkarsh Agarwal","Monojit Choudhury"],"title":"Geometry of Values: Task Vector Composition for Ethical Preference Alignment in Language Models","abstract":"Large Language Models (LLMs) are increasingly deployed in applications that must weigh clashing moral values, yet even strong models exhibit hidden biases and brittle instruction-following across languages. We introduce a 12,000-instance dataset of two-option dilemmas covering pairwise three value conflicts: Honesty vs. Justice, Justice vs. Autonomy, and Autonomy vs. Honesty, along with their translations into Hindi, Arabic, Spanish, and Chinese, to probe cross-lingual behavior. Benchmarking on GPT-5-mini reveals that it consistently favors Honesty over Autonomy across all five languages when no policy is given. The Llama-3.2-1/3B models exhibit strong first-option bias; however, both plain fine-tuning and Direct Preference Optimization fine-tuning effectively remove this bias, increasing accuracy to greater than 98%. In order to decouple the effect of learning correlations in the datase"},{"id":"arxiv:2609.21229","tags":["VLM Training","Reasoning","Planning","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21229","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21229.pdf","arxiv":"https://arxiv.org/abs/2609.21229","date":"2026-09-21","topics":["VLM Training","Reasoning","Planning","Fine-tuning"],"authors":["Zhiyuan Gao","Yanxiang Zhan","Mohammad Khoshnazar","Jeroen Schäfer","Michael Beetz"],"title":"KnowDemo: Knowledge-Guided Robot Demonstration Generation from Human Videos","abstract":"Learning robot manipulation policies typically requires substantial demonstration data, which are costly to collect on real robots. Recent methods generate robot demonstrations from human videos by adapting recovered motion and validating the resulting trajectories in simulation. However, methods centered on motion-reference adaptation can limit behavioral diversity by retaining the demonstrated contact strategies and subtask orders, while insufficient understanding of task requirements and scene relations can reduce demonstration generation efficiency by generating invalid candidates. To address these limitations, we propose KnowDemo, a framework that uses structured manipulation knowledge from human videos to generate diverse robot demonstrations for a target workspace. To distinguish task requirements from demonstration-specific choices, we develop a knowledge extraction and reasoning"},{"id":"arxiv:2609.22043","tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"source":"arxiv","url":"https://arxiv.org/abs/2609.22043","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22043.pdf","arxiv":"https://arxiv.org/abs/2609.22043","date":"2026-09-21","topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"authors":["Yiming Zhang","Jinghong Zhang","Haoran Zhao","Yiren Ma","Chunlei Zhao"],"title":"An Interpretable Memory Decision Controller for LLM Agents Based on Three-Signal Complementarity: Decoupling Confidence and Consistency","abstract":"Memory systems for large language models have focused predominantly on efficient retrieval, whereas the decision of whether retrieved memories should be trusted has received comparatively little attention. When the memory store contains conflicting positions, standard retrieval-augmented generation (RAG) blindly injects memories and amplifies hallucinations: in models susceptible to memory injection, the RAG hallucination rate under conflicting memories is markedly higher than that of a memory-free baseline. Inspired by memory signaling mechanisms in the prefrontal cortex, we propose the Memory Decision Layer (MDL), a zero-parameter memory decision controller situated between the retrieval and generation stages. Its core is a three-signal complementary encoder that fuses relevance, reliability, and task risk through QR-based orthogonal subspace projection and a meta-working-memory signal"},{"id":"arxiv:2609.22040","tags":["VLM Training","Reasoning","Planning","Evaluation"],"source":"arxiv","url":"https://arxiv.org/abs/2609.22040","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22040.pdf","arxiv":"https://arxiv.org/abs/2609.22040","date":"2026-09-21","topics":["VLM Training","Reasoning","Planning","Evaluation"],"authors":["Erik Deinzer","Naya Baslan","Luca Paparusso","Narunas Vaskevicius","Peter Knott","Luigi Palmieri"],"title":"PRIME: Perception Feedback with Situational Memory Embeddings in VLA Models","abstract":"Current Vision-Language-Action (VLA) models for autonomous driving operate primarily through feedforward inference across the perception--reasoning--planning hierarchy. While modern architectures maintain temporal recurrence within the perceptual module, early perception remains blind to downstream reasoning and navigation goals, processing visual inputs agnostically without prioritizing cues informed by prior decisions. To bridge this gap, this paper introduces PRIME, a learned feedback mechanism that conditions the VLA perceptual queries on a novel Situational Memory. By aggregating latent representations of past perception, reasoning, navigation goals, and predicted behaviors across an L-step window via cross-attention, PRIME enables intent-driven perceptual attention at minimal computational cost, adding only a maximum of 29.7M parameters (0.41% of the 7.3B-parameter base model). Eva"},{"id":"arxiv:2609.21857","tags":["LLM Training","Alignment","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21857","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21857.pdf","arxiv":"https://arxiv.org/abs/2609.21857","date":"2026-09-21","topics":["LLM Training","Alignment","Fine-tuning"],"authors":["Tim Krabbe","Xiaodan Shi"],"title":"Do Personality-Tuned LLMs Make Better Social Agents?","abstract":"LLMs are increasingly used in social simulations for socially interactive agents and robots, offering more flexibility than rule-based systems. However, even though they mimic human behaviour very well, there is a persistent alienness to them. This work investigates whether personality-aware fine-tuning can reduce this gap by improving the consistency and controllability of personality-conditioned dialogue generation compared with instruction prompting alone. We fine-tune two small open-weight LLMs, Qwen2.5-7B-Instruct and Ministral-8B-Instruct, using a corpus that combines personality-labelled social media posts and dialogues to create a personality-based dialogue engine for social simulation. The resulting models are evaluated across multiple social interaction scenarios using three independent LLM judges, which assess personality fidelity and provide evidence-based behavioral interpre"},{"id":"arxiv:2609.20981","tags":["Reasoning","Evaluation","Reflection"],"source":"arxiv","url":"https://arxiv.org/abs/2609.20981","upvotes":0,"submittedDate":"2026-09-17","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.20981.pdf","arxiv":"https://arxiv.org/abs/2609.20981","date":"2026-09-21","topics":["Reasoning","Evaluation","Reflection"],"authors":["Wei Cai","Jian Zhao","Yuchen Yuan","Xuelong Li"],"title":"CaLR: Causal Latent Revision for Robust Diffusion Reasoning","abstract":"Autoregressive (AR) models suffer from local greediness, while diffusion language models (DLMs) often lack the strict causal structure required for reasoning. To combine the advantages and overcome the drawbacks of the dual, we propose Causal Latent Revision (CaLR), a framework that reformulates reasoning as constrained latent optimization. By adopting a causal topology matrix (CTM) from an expert model and implicit differentiation, CaLR performs gradient-guided ``thought revision\" to enforce logical consistency, enabling dynamic self-correction of intermediate steps during parallel generation. Empirically, CaLR achieves SOTA DLM performance on complex benchmarks, surpassing strong AR baselines and demonstrating superior robustness in constrained tasks like Sudoku."},{"id":"arxiv:2609.21465","tags":["Multi-Agent","Evaluation","Data Engine"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21465","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21465.pdf","arxiv":"https://arxiv.org/abs/2609.21465","date":"2026-09-21","topics":["Multi-Agent","Evaluation","Data Engine"],"authors":["Haolin He","Yunfei Chu","Qi Chen","Wen Huang","Yuan Feng","Muzhi Zhu","Zheqi Dai","Haoning Xu","Dongchao Yang","Chunyat Wu","Zining Liang","Zhengxi Liu","Xiquan Li","Xie Chen","Xize Cheng","Qize Yang","Jin Xu","Qiuqiang Kong"],"title":"OmniVChat: Synthesizing, Benchmarking, and Training for Native Audio-Visual Dialogue","abstract":"We define OmniVChat (Omni Video Chat) as the task of native audio-visual dialogue between a user and an omni model. In OmniVChat, omni models directly and simultaneously receive audio and video from a user and return text. The user's query is embedded in the audio and video, without a separate text question, external captioning, or speech recognition. Direct audio-visual input reduces external latency and computation while preserving perceptual cues. However, research on OmniVChat faces two constraints: data availability and evaluation. Recordings of people using their own devices are scarce. Furthermore, a good reply often needs to account for the user's surroundings, facial expressions, and nearby objects, and such responses can be expressed in many different ways, making keyword matching unreliable for evaluating reply quality. Recent progress in agent systems and video generation mak"},{"id":"arxiv:2609.21686","tags":["Tool Use","Evaluation","Alignment"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21686","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21686.pdf","arxiv":"https://arxiv.org/abs/2609.21686","date":"2026-09-21","topics":["Tool Use","Evaluation","Alignment"],"authors":["Tao Huang","Guosen Wu","Guolong Zheng","Jiayang Meng","Chen Hou","Xu Yang","Xuechao Yang","Feng Xia"],"title":"CIPL: A Channel-Aware Framework for Recoverable Privacy Leakage in LLM Agents","abstract":"Privacy leakage in LLM agents is commonly evaluated within individual components such as memory, retrieval, or tool-use pipelines, which makes it difficult to distinguish internal exposure from information that an external observer can actually recover. We present CIPL (Channel Inversion for Privacy Leakage), a channel-aware evaluation framework for black-box privacy leakage in LLM agents. CIPL represents a target through sensitive source, selection, assembly, execution, observation, and extraction stages and evaluates the transition from selected sensitive units to attacker-recoverable output under a shared protocol. Experiments across memory-based, retrieval-mediated, and tool-mediated targets, together with a BrowserUse live-agent case study, show that storage labels alone do not determine recoverability. Memory targets form a near-saturated reference case, retrieval-mediated leakage "},{"id":"arxiv:2609.20850","tags":["Reasoning","Evaluation","Alignment"],"source":"arxiv","url":"https://arxiv.org/abs/2609.20850","upvotes":0,"submittedDate":"2026-08-08","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.20850.pdf","arxiv":"https://arxiv.org/abs/2609.20850","date":"2026-09-21","topics":["Reasoning","Evaluation","Alignment"],"authors":["Yueming Lyu","Yilian Shi","Haoxiang Tan","Linzhuang Zou","Qihao Wang","Guihua Yu","Jie Qin","Xin Gao","Chenyang Si","Jing Dong","Caifeng Shan"],"title":"MME-Safety: A Fine-grained Benchmark for Safety Evaluation of MLLMs","abstract":"While Multimodal Large Language Models (MLLMs) show remarkable advancements, their cross-modal capabilities introduce complex vulnerabilities that easily bypass unimodal filters. Existing benchmarks lack fine-grained intent-related annotations and rely on unidimensional metrics, hindering comprehensive robustness evaluation. To address this, we propose MME-Safety, a rigorously verified benchmark featuring a unique four-dimensional annotation schema that categorizes risk scenarios, harm severity, and modality-specific stealth levels. Furthermore, we introduce a hierarchical evaluation framework to assess fundamental response reliability, actual risk exposure, and the structural integrity of defensive behaviors. Extensive zero-shot evaluations across 17 state-of-the-art MLLMs provide a comprehensive safety profile of current multimodal systems. Our analysis systematically investigates cros"},{"id":"arxiv:2609.21378","tags":["Reasoning","Evaluation","RL for LLM"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21378","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21378.pdf","arxiv":"https://arxiv.org/abs/2609.21378","date":"2026-09-21","topics":["Reasoning","Evaluation","RL for LLM"],"authors":["Qiang Zhang","Ruixue Ding","Fanrui Zhang","Xi Chen","Boli Chen","Shihang Wang","Yinfeng Huang","Yi Zheng","Pengjun Xie","Kaipeng Zhang","Jiawei Liu","Zheng-Jun Zha"],"title":"ArenaFlow: From Trajectory Ranking to Hierarchical Credit Propagation for Open-Ended Agent RL","abstract":"Reinforcement learning has substantially improved large language model (LLM) agents in verifiable domains, but remains difficult to apply to open-ended agent tasks, where solutions are diverse and reliable scalar rewards are hard to obtain. Recent pairwise evaluation methods alleviate reward discrimination collapse by replacing pointwise scoring with relative preferences. However, they still compress rich comparative feedback into a single trajectory-level reward, obscuring decisive intermediate steps and preventing successful behaviors from being consolidated into reusable skills. We propose ArenaFlow, a hierarchical credit propagation framework for open-ended agent reinforcement learning. ArenaFlow leverages tournament-based relative ranking to derive trajectory-level reward signals. Each comparison is further equipped with structured reflective evaluation, which reveals three types of"},{"id":"arxiv:2609.21187","tags":["LLM Training","Evaluation","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21187","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21187.pdf","arxiv":"https://arxiv.org/abs/2609.21187","date":"2026-09-21","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Md Tahmid Rahman Laskar","Xue-Yong Fu","Gundeep Singh","Karol Chang","Kevin Sanders","Shi Zong","Tania Habib","Julien Bouvier Tremblay","Shayna Gardiner","Harsh Saini","Matthias Lee","Elena Khasanova","Quinten McNamara","Shashi Bhushan TN"],"title":"When Better Turns Do Not Make Better Agents: Diagnosing the Gap Between Next-Turn Metrics and Workflow Success","abstract":"Agent models are frequently evaluated one decision at a time, where the model predicts the next action based on the gold interaction history, which is scored against a reference. We investigate whether improvement under this protocol is predictive of improved autonomous workflow execution. We study pre-SFT and supervised fine-tuned (SFT) Qwen3 models at 4B and 14B parameters and Gemma 3 models at 4B and 12B parameters on multi-turn customer-support workflows. We find that SFT consistently improves text-turn success, and that overall next-turn success increases for every model under gold-history evaluation. However, these improvements do not transfer to autonomous workflow execution. Tool-specific gains also vary across metrics and models. None of the four SFT models succeeds under holistic workflow evaluation, with strict trajectory completion reaching at most 10.4% workflow success. Our"},{"id":"arxiv:2609.20846","tags":["Post-Training","Reasoning","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.20846","upvotes":0,"submittedDate":"2026-08-05","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.20846.pdf","arxiv":"https://arxiv.org/abs/2609.20846","date":"2026-09-21","topics":["Post-Training","Reasoning","Fine-tuning"],"authors":["Polina Tsvilodub","Max Höth","Michael Franke","Björn Deiseroth","Carina Kauf"],"title":"Rewarding Efficient Reasoning Improves Abstention on Underspecified Tasks in Reasoning Models","abstract":"While modern large reasoning models (LRMs) excel at providing correct answers in many tasks, we provide additional evidence for the observation that they often struggle with a critical capability: knowing when to abstain from answering. We analyze this gap by comparing LRM behavior to results from a human study, revealing that human reasoning effort on unanswerable tasks is upper-bounded by answerable tasks, whereas LRMs waste computational resources by generating longer Chains of Thought (CoTs) on unanswerable than on answerable prompts. To overcome this inefficiency, we take inspiration from a resource-rational perspective on human cognition and introduce a novel GRPO reward that encourages efficient reasoning about whether the task contains all the information needed to solve it. Fine-tuning several 4B LRMs with this reward leads to human-like abstention performance gains (+12.8% on a"},{"id":"arxiv:2609.21859","tags":["Multi-Agent","Reasoning","Planning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21859","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21859.pdf","arxiv":"https://arxiv.org/abs/2609.21859","date":"2026-09-21","topics":["Multi-Agent","Reasoning","Planning"],"authors":["Jiacheng Lin","Zifeng Wang","Zheng Chen","Erick Scott","Ziwei Yang","Fanyang Yu","Sheng Zhong","Jimeng Sun"],"title":"TrialAtlas: Multi-Agent Research Organization for Clinical Trial Design and Optimization","abstract":"Nearly 90% of drugs entering clinical development ultimately fail, despite billions of dollars in investment. Pharmaceutical companies therefore rely on clinical development planning (CDP) and probability of technical and regulatory success assessment to anticipate development risks, yet these decisions remain labor-intensive and subjective, requiring experts across clinical science, statistics, regulatory affairs, and competitive intelligence to jointly acquire, synthesize, and reason over heterogeneous evidence. Here, we introduce TrialAtlas, a memory-augmented multi-agent research organization for CDP that mirrors this collaborative process by coordinating specialized agents for literature synthesis, competitive trial intelligence, regulatory precedent analysis, and integrated reasoning over trial design and development risk. TrialAtlas further learns from historical clinical trials a"},{"id":"arxiv:2609.21554","tags":["Reasoning","Evaluation","RL for LLM"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21554","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21554.pdf","arxiv":"https://arxiv.org/abs/2609.21554","date":"2026-09-21","topics":["Reasoning","Evaluation","RL for LLM"],"authors":["Arash Lagzian","Srinivas Anumasa","Dianbo Liu"],"title":"MIRAGE: Multi-Perspective Creative Language Model Reasoning with Reinforcement Learning Guidance","abstract":"Recent advances in Large Language Models (LLMs) have revolutionized artificial intelligence and how human interact with AIs. Despite impressive advancements, LLMs struggle with complex mathematical, scientific, and logical tasks. Inspired by human cognitive flexibility - our ability to dynamically switch mental perspectives - we propose MIRAGE (Multi-perspective Inference-time Reasoning via Agent-Guided Exploration), a novel inference-time creative thinking framework. MIRAGE includes a Selector that prioritizes effective conceptual perspectives (e.g., algebraic, probabilistic) and a Reasoner that sequentially solves tasks until a confident solution emerges, otherwise aggregating multiple perspectives. Tested on GSM8K, MATH500, MMLU-Pro, and Game-of-24 benchmarks, MIRAGE consistently outperforms methods like Chain-of-Thought and diverse prompting ensembles, significantly boosting accuracy"},{"id":"arxiv:2609.21989","tags":["Evaluation","Interpretability","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21989","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21989.pdf","arxiv":"https://arxiv.org/abs/2609.21989","date":"2026-09-21","topics":["Evaluation","Interpretability","Fine-tuning"],"authors":["Camilo Carvajal Reyes","Felipe Tobar"],"title":"Time series generation with spectrally aligned latent flow matching","abstract":"Latent flow models have proven to be a reliable and cost-effective method for time series generation. However, the latent compression induces unwanted artefacts, such as a spectral mismatch with respect to the underlying dataset, thus hindering their use as training surrogates. In this article, we propose a spectrally-aligned latent-flow time series generator, where the latent space for flow matching is trained to preserve dynamical properties that are relevant for the suitability of synthetic samples. We find that incorporating fine-tuning losses based on canonical signal representations such as the Fourier, wavelet and signature transforms helps overcome these issues. The interpretability of these transformations allows us to ensure that the synthetic signals are aligned with the true ones in terms of relevant features, such as smoothness or targeted spectral content, as opposed to rel"},{"id":"arxiv:2609.22064","tags":["LLM Training","Evaluation","Alignment"],"source":"arxiv","url":"https://arxiv.org/abs/2609.22064","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.22064.pdf","arxiv":"https://arxiv.org/abs/2609.22064","date":"2026-09-21","topics":["LLM Training","Evaluation","Alignment"],"authors":["Alexandre Andre","Shivashriganesh P. Mahato","Vinam Arora","Keshav Balaji","Divyansha Lachi","Nanda H. Krishna","Jingyun Xiao","Yizi Zhang","Ximeng Mao","Wenrui Ma","Han Yu","International Brain Laboratory","Daniel Birman","Niccolò Bonacchi","Gaelle A. Chapuis","Joana A. Catarino","Felicia Davatolhagh","Mayo Faulkner","Laura Freitas-Silva","Fei Hu","Julia M. Huntenburg","Anup Khanal","Inês Laranjeira","Petrina Lau","Guido T. Meijer","Nathaniel J. Miska","Jean-Paul Noel","Alejandro Pan-Vazquez","Georg Raiser","Cyrille Rossant","Karolina Z. Socha","Anne E. Urai","Miles J. Wells","Steven J. West","Olivier Winter","Blake Richards","Guillaume Lajoie","Cole Hurwitz","Mehdi Azabou","Matthew R. Whiteway","Liam Paninski","Eva L. Dyer"],"title":"BrainWideBench: Benchmarking large-scale pretraining and across-animal transfer in multi-region neural recordings","abstract":"Advances in large-scale neural recording have made it possible to collect data across many animals and distributed brain regions, raising the question of whether this scale can be exploited to learn general-purpose neural representations transferable across diverse downstream tasks. Yet, progress toward this goal has been limited by fragmented evaluation protocols and a narrow focus on individual task domains. Here, we present BrainWideBench, a benchmark for evaluating across-animal transfer on multi-region neural recordings, built on the International Brain Laboratory Brainwide Map dataset of neural and behavioral recordings spanning 276 brain regions from 139 mice performing a sensory-guided decision-making task. The benchmark is organized around three complementary task suites that evaluate whether learned representations support downstream decoding of behavior, can predict masked or "},{"id":"arxiv:2609.21945","tags":["Planning","Memory","Evaluation"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21945","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21945.pdf","arxiv":"https://arxiv.org/abs/2609.21945","date":"2026-09-21","topics":["Planning","Memory","Evaluation"],"authors":["Adewumi Augustine Adepitan","Christopher J. Haruna","Oluwasegun Adegoke","Ayooluwatomiwa Ajiboye","Oluwatobi Oluwasakin"],"title":"Learning to Move Cities: Deep Meta-Models and Reinforcement Policies for Calibration and Control in Urban Networks","abstract":"Urban transportation networks present complex optimization challenges spanning calibration of high-fidelity simulators and real-time operational control. This paper presents a shared latent-space framework that connects simulator calibration and reinforcement learning control through a common learned representation of urban traffic dynamics. First, we develop a combinatorial MLP-autoencoder architecture that learns low-dimensional manifolds linking simulator inputs (origin-destination demand, network parameters) to outputs (travel times, congestion patterns), enabling efficient Bayesian optimization for calibration. This approach demonstrates superior sample efficiency compared to traditional dimension reduction methods, achieving better fit to observational data within fixed computational budgets. Second, we implement a deep Q-learning agent with experience replay and target networks to"},{"id":"arxiv:2609.21288","tags":["LLM Training","Evaluation","Fine-tuning"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21288","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21288.pdf","arxiv":"https://arxiv.org/abs/2609.21288","date":"2026-09-21","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Chenqian Le","Beatrice Fumagalli","Yasamin Esmaeili","Xupeng Chen","Tianyu He","Nikasadat Emami","Adeen Flinker","Yao Wang"],"title":"Multi-Subject Pretraining Enables Short-Calibration Personalization for Closed-Corpus Surface EMG Speech Decoding","abstract":"Surface electromyography (sEMG)-based silent speech interfaces are limited by cross-user variability and calibration burden. We study a limited-data setting in which each of 27 speech-typical participants contributed less than 0.5 h of data (21.3 min on average) across Aloud and Mimed speech. Within a closed 50-sentence corpus, we used leave-one-subject-out evaluation, initializing from a released single-subject checkpoint, pretraining on non-held-out participants, and fine-tuning on the target participant. This pipeline achieved 21.7% character error rate (CER) and 31.9% word error rate (WER), compared with 49.3% CER without target-subject calibration and 68.0% CER for direct checkpoint fine-tuning. Multi-subject pretraining from random initialization followed by fine-tuning reached 44.9% CER and did not converge under the fixed schedule in 5 of 27 folds, indicating substantial optimiza"},{"id":"arxiv:2609.21425","tags":["Agentic Search","LLM Training","Evaluation"],"source":"arxiv","url":"https://arxiv.org/abs/2609.21425","upvotes":0,"submittedDate":"2026-09-18","announceDate":"2026-09-21","pdf":"https://arxiv.org/pdf/2609.21425.pdf","arxiv":"https://arxiv.org/abs/2609.21425","date":"2026-09-21","topics":["Agentic Search","LLM Training","Evaluation"],"authors":["Delun Kong","Wanyun Ling","Chenxi Liu","Ziyue Li"],"title":"Tracing the Evidence Behind Zero-Shot Time-Series Forecasting: A Source-First Taxonomy and Audit Framework","abstract":"Zero-shot time-series forecasting (TSF) is often described as forecasting without target-specific parameter updates, but that training-status condition does not specify what evidence the system may use. A frozen language model prompted with serialized values, a time-series model pretrained on broad forecasting corpora, and a retrieval-augmented forecaster may all satisfy the no-update condition while drawing on different transferable evidence. This paper argues that zero-shot TSF should therefore be governed as an evidence-access claim. We propose a source-first taxonomy that separates three primary evidence sources---frozen LLM prior reuse, parametric time-series pretraining, and retrieval-augmented external memory---from the architectures that implement them. After the source is identified, four additional audit questions remain: task interface, forecast object and scoring, prediction-"}],"archive":[],"latestPath":"data/latest.json"};
